import 'dart:convert';

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../domain/deck_repository.dart';
import '../domain/flashcard.dart';

/// Reads the deck generated by `tool/import_handbook.dart`.
final class AssetDeckRepository implements DeckRepository {
  const AssetDeckRepository({this.bundle, this.path = defaultPath});

  static const defaultPath = 'assets/cards.json';

  /// Defaults to [rootBundle].
  final AssetBundle? bundle;
  final String path;

  @override
  Future<Deck> load() async {
    final String source;
    try {
      source = await (bundle ?? rootBundle).loadString(path);
    } on FlutterError catch (e) {
      throw DeckLoadException(e);
    }
    return decodeDeck(source);
  }
}

/// Parses the JSON asset. Throws a [DeckLoadException] on malformed input.
Deck decodeDeck(String source) {
  try {
    final json = jsonDecode(source) as Map<String, Object?>;
    final sourceInfo = json['source']! as Map<String, Object?>;
    return Deck(
      repository: sourceInfo['repository']! as String,
      commit: sourceInfo['commit']! as String,
      chapters: [
        for (final c in json['chapters']! as List<Object?>)
          _chapter(c! as Map<String, Object?>),
      ],
      cards: [
        for (final c in json['cards']! as List<Object?>)
          _card(c! as Map<String, Object?>),
      ],
    );
  } on FormatException catch (e) {
    throw DeckLoadException(e);
  } on TypeError catch (e) {
    throw DeckLoadException(e);
  } on ArgumentError catch (e) {
    throw DeckLoadException(e);
  }
}

Chapter _chapter(Map<String, Object?> json) => Chapter(
  id: json['id']! as String,
  number: json['number']! as int,
  title: json['title']! as String,
  path: json['path']! as String,
);

Flashcard _card(Map<String, Object?> json) => Flashcard(
  id: json['id']! as String,
  chapterId: json['chapter']! as String,
  level: Level.values.byName(json['level']! as String),
  question: json['question']! as String,
  answer: json['answer']! as String,
  anchor: json['anchor']! as String,
);

final deckRepositoryProvider = Provider<DeckRepository>(
  (ref) => const AssetDeckRepository(),
);
